using System;

public static class CheckoutPriceCalculatorTests
{
    public static void Main()
    {
        CalculatesStandardCheckoutPrice();
        AddsExpeditedShippingBeforeTax();
        RoundsFinalTotalToEvenCent();
        RejectsInvalidInputs();
    }

    private static void CalculatesStandardCheckoutPrice()
    {
        AssertEqual(
            "94.50",
            CheckoutPriceCalculator.Calculate("100.00", "0.10", "0.05", ShippingMethod.Standard));
    }

    private static void AddsExpeditedShippingBeforeTax()
    {
        AssertEqual(
            "110.25",
            CheckoutPriceCalculator.Calculate("100.00", "0.10", "0.05", ShippingMethod.Expedited));
    }

    private static void RoundsFinalTotalToEvenCent()
    {
        AssertEqual(
            "1.00",
            CheckoutPriceCalculator.Calculate("1.005", "0", "0", ShippingMethod.Standard));
        AssertEqual(
            "1.02",
            CheckoutPriceCalculator.Calculate("1.015", "0", "0", ShippingMethod.Standard));
    }

    private static void RejectsInvalidInputs()
    {
        AssertThrows<ArgumentException>(
            () => CheckoutPriceCalculator.Calculate("1", "1.01", "0", ShippingMethod.Standard));
        AssertThrows<ArgumentException>(
            () => CheckoutPriceCalculator.Calculate(".1", "0", "0", ShippingMethod.Standard));
        AssertThrows<ArgumentOutOfRangeException>(
            () => CheckoutPriceCalculator.Calculate("1", "0", "0", (ShippingMethod)42));
    }

    private static void AssertEqual(string expected, string actual)
    {
        if (!string.Equals(expected, actual, StringComparison.Ordinal))
        {
            throw new InvalidOperationException("Expected " + expected + " but received " + actual + ".");
        }
    }

    private static void AssertThrows<TException>(Action action)
        where TException : Exception
    {
        try
        {
            action();
        }
        catch (TException)
        {
            return;
        }

        throw new InvalidOperationException("Expected " + typeof(TException).Name + ".");
    }
}

